def apply(b):
    for (s, n), f in F.items():
        if s != b.sid:
            continue
        q = b.Q[n - 1]
        for k, v in f.items():
            if k == 'hint': q['hint'] = v
            elif k == 'desc': q['desc'] = v
            elif k == 'expl': q['expl'] = v
            elif k == 'sub_desc':
                assert v[0] in q['desc'], (s, n, 'desc')
                q['desc'] = q['desc'].replace(*v)
            elif k == 'sub_expl':
                assert v[0] in q['expl'], (s, n, 'expl')
                q['expl'] = q['expl'].replace(*v)
            elif k == 'prefix_desc': q['desc'] = v + q['desc']
            elif k == 'title': q['title'] = v
            elif k == 'sol': q['sol'] = v
            elif k == 'checks': q['checks'] = v
            elif k == 'add_checks': q['checks'] = q['checks'] + v
            elif k == 'sub_setup':
                assert v[0] in q['setup'], (s, n, 'setup')
                q['setup'] = q['setup'].replace(*v)
            elif k == 'sub_check0':
                q['checks'][0] = dict(q['checks'][0], cmd=v)
